ect()`.\\n\\n## Examples\\n\\n### Upsert a single row using a unique key\\n\\n```ts\\n// Upserting a single row, overwriting based on the 'username' unique column\\nconst { data, error } = await supabase\\n  .from('users')\\n  .upsert({ username: 'supabot' }, { onConflict: 'username' })\\n\\n// Example response:\\n// {\\n//   data: [\\n//     { id: 4, message: 'bar', username: 'supabot' }\\n//   ],\\n//   error: null\\n// }\\n```\\n\\n### Upsert with conflict resolution and exact row counting\\n\\n```ts\\n// Upserting and returning exact count\\nconst { data, error, count } = await supabase\\n  .from('users')\\n  .upsert(\\n    {\\n      id: 3,\\n      message: 'foo',\\n      username: 'supabot'\\n    },\\n    {\\n      onConflict: 'username',\\n      count: 'exact'\\n    }\\n  )\\n\\n// Example response:\\n// {\\n//   data: [\\n//     {\\n//       id: 42,\\n//       handle: \\\"saoirse\\\",\\n//       display_name: \\\"Saoirse\\\"\\n//     }\\n//   ],\\n//   count: 1,\\n//   error: null\\n// }\\n```\\n\\n### Upsert your data\\n\\n```ts\\nconst { data, error } = await supabase\\n  .from('instruments')\\n  .upsert({ id: 1, name: 'piano' })\\n  .select()\\n```\\n\\n### Handling errors\\n\\n```js\\nconst { data, error } = await supabase.from('instruments').upsert({ id: 1, name: 'piano' }).select()\\nif (error) console.error(error)\\n```\\n\\n### Bulk Upsert your data\\n\\n```ts\\nconst { data, error } = await supabase\\n  .from('instruments')\\n  .upsert([\\n    { id: 1, name: 'piano' },\\n    { id: 2, name: 'harp' },\\n  ])\\n  .select()\\n```\\n\\n### Upserting into tables with constraints\\n\\n```ts\\nconst { data, error } = await supabase\\n  .from('users')\\n  .upsert({ id: 42, handle: 'saoirse', display_name: 'Saoirse' })\\n  .select()\\n```\",\"language\":\"JAVASCRIPT\",\"methodName\":\"upsert\"},{\"title\":\"Upsert data: upsert()\",\"href\":\"https://supabase.com/docs/reference/swift/upsert\",\"content\":\"# Swift Reference\\n\\nUpsert data: upsert()\\n\\n\\n\\